package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Troll with its own model and texture. Generated by shadw-mod mob. */
public class TrollRenderer extends MobRenderer<Troll, TrollModel.State, TrollModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/troll.png");

	public TrollRenderer(EntityRendererProvider.Context context) {
		super(context, new TrollModel(context.bakeLayer(TrollModel.LAYER)), 0.9F);
	}

	@Override
	public TrollModel.State createRenderState() {
		return new TrollModel.State();
	}

	@Override
	public void extractRenderState(Troll entity, TrollModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(TrollModel.State state) {
		return TEXTURE;
	}
}
